def clean(s):
    return re.sub(r'"(?:\\.|[^"\\])*"|/\*.*?\*/|//[^\n]*',
                  lambda m: m[0] if m[0].startswith('"') else ' ', s, flags=re.S)

def function(s, name):
    m = re.search(r'(?m)^[\w \t*]+\b'+re.escape(name)+r'\s*\([^;]*?\)\s*\{', s)
    assert m, name
    end=m.end();depth=1
    while depth:
        depth += (s[end]=='{')-(s[end]=='}'); end+=1
    return s[m.start():end]

